import{_ as t,o as n,c as a,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy technical acceptance checklist","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","frontmatter":{"title":"Chainy technical acceptance checklist","description":"Historical snapshot preserved November 11, 2026 before the technical-document cleanup.\\nUse the current document for the active design.","source":"docs/archive/pre-lesson-collection-2026-11-11/requirements/technical-requirements.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/technical-requirements.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/technical-requirements.md"}'),i={name:"content/docs/archive/pre-lesson-collection-2026-11-11/requirements/technical-requirements.md"};function o(c,e,s,d,l,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<div><blockquote><p>Historical snapshot preserved November 11, 2026 before the technical-document cleanup. Use the <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">current document</a> for the active design.</p></blockquote><h1 id="chainy-technical-acceptance-checklist">Chainy technical acceptance checklist<a class="header-anchor" href="#chainy-technical-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Updated November 11, 2026 for the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>. This is a planned verification contract, not a tested implementation report. <strong>Work is limited to documentation and setup until the owner gives final approval for development.</strong> Christian owns technical integration and acceptance; agent preparation does not replace his responsibility lane or establish runtime evidence.</p><h2 id="planned-technical-checks">Planned technical checks<a class="header-anchor" href="#planned-technical-checks" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Area</th><th>Required behavior to verify after development is authorized</th></tr></thead><tbody><tr><td>Build identity and device</td><td>Record source revision, actual Unity version, Android settings, SQLite binding, and tested device. Retain API 25 minimum installation and Android 10/API 29 reference testing. The reference device has 4 GB physical RAM, 128 GB total storage, and a reported 2.3 GHz octa-core CPU.</td></tr><tr><td>Architecture</td><td>Reuse project architecture: views present state, handlers route commands, services own gameplay, typed events notify, and the database owner controls SQL/transactions. Keep rules separate from scene presentation.</td></tr><tr><td>World and lesson state</td><td>Keep separate tutorial, current lesson/step, recorded entries, collection-complete, and required-review-complete facts per profile. Derive Web3 → Blockchain → AI access from the approved completion rule.</td></tr><tr><td>Content identity</td><td>Preserve the GDD&#39;s 39 stable LC lesson IDs and nine activity identities. Keep teaching order separate from encyclopedia alphabetical display. Content/schema versions must be explicit.</td></tr><tr><td>Scene transitions</td><td>Save completed prerequisites before launch; accept one launch at a time; remember the originating island and safe return point. Failed loads allow retry without losing required quest evidence.</td></tr><tr><td>Activity lifecycle</td><td>Retry stays inside the minigame. Exit returns to its island without granting the entry. Saved prerequisites persist, and successful replay cannot duplicate completion.</td></tr><tr><td>Atomic lesson checkpoints</td><td>Save lesson completion, encyclopedia entry, and next objective together. Failed or repeated saves must not advance the displayed quest prematurely or duplicate an entry.</td></tr><tr><td>Required review and unlock</td><td>Save approved review completion and next-world access consistently. Distinguish abandonment, first responses, corrected answers if that policy is chosen, and completed replay. Replay abandonment cannot revoke an existing unlock.</td></tr><tr><td>Recovery and profiles</td><td>Restore successful checkpoints on relaunch. Clear old in-memory progress on profile switch. Preserve unknown/incompatible saves with recovery feedback instead of silently resetting them. Define migrations only after inspecting the actual schema.</td></tr><tr><td>Input and backgrounding</td><td>Only one interaction receives input. Dialogue, encyclopedia, quests, pause, loading, and pending saves block inappropriate world input. Clear held joystick input on overlay transitions and Android background/resume.</td></tr><tr><td>AI and network boundary</td><td>AI activities use labeled offline teaching simulations. Do not claim authored branches train a model or generate live content. No real wallet, secret entry, public blockchain, cloud model, or network-dependent gameplay is required.</td></tr><tr><td>Accessibility and performance</td><td>Check text, touch targets, feedback, audio-muted use, and color-independent cues on the reference phone. Measure load/recovery/performance behavior; editor-only or higher-spec results do not establish Android acceptance.</td></tr></tbody></table><p>The proposed five-question correction policy remains pending owner choice. Do not encode a fixed question count, pass percentage, or correction requirement as an approved contract until that decision is recorded. The draft bank and activity instructions are prepared content, not a validated assessment or evidence of implemented scenes.</p><p>Use synthetic profiles and fictional lesson data for later checks. Do not record IMEI, MAC address, learner identities, credentials, or signing keys in repository evidence. The local demo profile remains distinct from authentication, teacher enrollment, pairing, or collection services. JSON may be an export format; SQLite remains the local progress store.</p><h2 id="source-and-evidence-routes">Source and evidence routes<a class="header-anchor" href="#source-and-evidence-routes" aria-label="Link to this section">​</a></h2><p>Read <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">product acceptance</a>, <a href="/Chainy-Docs/content/docs/design/app-flow.html">player flow</a>, <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/hardware-validation.html">device checks</a>, and the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html">database reference</a>. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/technical-design.html">technical design</a> contains reusable architecture and dated V2 material; where gameplay rules conflict, the current GDD and final owner decisions govern. A dated static source assessment is not a passing APK check. Later reports must name the build, device, expected result, actual result, and evidence location.</p><h2 id="historical-scope-boundary">Historical scope boundary<a class="header-anchor" href="#historical-scope-boundary" aria-label="Link to this section">​</a></h2><p>The former November 10 checklist required a fictional wallet reward/purchase, coordinated balance/inventory/ledger persistence, repair of that same purchase record, and a conditional actual classifier. Those economy-led checks do not govern the new 39-lesson game. The historical V2 definitions remain in <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.html#historical-v2-requirements">product acceptance</a> for traceability. Existing work is not declared complete or obsolete solely because a requirement changed; reconcile it against the approved design later.</p><p>No code, schema migration, scene edit, test execution, or build is authorized by this checklist. <strong>Pre-final remains November 21, 2026</strong>, with integration, device QA, manuscript evidence, and rehearsal time still required.</p></div>',1)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
